import React from "react";

const AddDivInputsFraction = ({ nomerator, denominator, setterFuction }) => {
  return (
    <div>
      <table>
        <tbody>
          <tr className="">
            <input
              value={divisionInputs.numerator2}
              onChange={(e) =>
                setDivisionInputs({
                  ...divisionInputs,
                  numerator2: e.target.value,
                })
              }
              id="divisionNum2"
              className="input digit-input"
            />
          </tr>
          <tr className="line-tr">
            <div class="line-input"></div>
          </tr>
          <tr>
            <input
              value={divisionInputs.denominator2}
              onChange={(e) =>
                setDivisionInputs({
                  ...divisionInputs,
                  denominator2: e.target.value,
                })
              }
              id="divisionDeno2"
              className="input digit-input "
            />
          </tr>
        </tbody>
      </table>
    </div>
  );
};

export default AddDivInputsFraction;
